mapper.select:
SELECT cpo.organization_id, cpo.organization_name as organization_name_n, cpo.bank_account_name as bank_account_name_n, product_id, organization_type, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ABS.INSTITUTION_TYPE' AND v.code_value = cpo.organization_type ) AS organization_type_n, bp_id, take_lead, bank_account_type, bank_account_id, contact_person, contact_phone, receiver_flag, organization_name, bank_account_name, bank_account_num, bank_branch_name, description, nvl(apfi.fee_amount_sum,0) fee_amount_sum FROM ct_abs_product_organization cpo left join ( select fee.organization_id, sum(fee.fee_amount) fee_amount_sum from ct_abs_pro_fee_info fee group by fee.organization_id ) apfi on apfi.organization_id=cpo.organization_id
and cpo.product_id = #{productId}
and cpo.receiver_flag = #{receiverFlag}
and cpo.organization_name = #{organizationName}
